// ===========================================================================
//  PICK THE DAILY TOPIC
//
//  You do NOT need to edit this node to get started. Your publication name,
//  LinkedIn page and email all live in the "Your Settings" node just before
//  this one -- change them there.
//
//  Come back here only when you want to change the TOPICS it writes about.
// ===========================================================================

// Everything you typed into "Your Settings" arrives here.
const s = $('Set Initial Parameters').first().json;

const PUBLICATION_NAME    = s.publication_name;
const PUBLICATION_PROMISE = s.publication_promise;
const ORG_ID              = s.linkedin_organization_id;
const APPROVAL_EMAIL      = s.approval_email;

// How the post format is chosen. Set on the "Your Settings" node:
//   'AUTO'         -- each topic posts in its natural format (see TOPICS below)
//   'SINGLE_IMAGE' -- always make a one-image post
//   'CAROUSEL'     -- always make a multi-image carousel
//
// AUTO is fixed per topic on purpose. Letting the model choose sounds nicer, but
// it settles on whichever format it likes and the other one silently stops being
// used. Deciding from the topic keeps both alive with no prompt tricks.
const POST_TYPE_MODE = s.post_type_mode;

// LinkedIn versions its whole REST surface by month and retires old ones.
// Bump this roughly twice a year.
const LINKEDIN_VERSION = '202604';

// LinkedIn multiImage accepts 2-20 images. Kept low deliberately: every slide
// is one more Gemini call, and every call is another chance for a run to die.
const MIN_SLIDES = 2;
const MAX_SLIDES = 5;

// 1:1 is the safe ratio for multiImage -- LinkedIn crops a mixed-aspect gallery
// to a single uniform tile. Note Gemini's image model accepts ONLY 1:1, 4:3,
// 3:4, 16:9 and 9:16. LinkedIn's other native portrait size, 4:5, is NOT a
// valid Gemini ratio and hard-errors the node -- do not "fix" this to 4:5.
const IMAGE_ASPECT = '1:1';
const IMAGE_SIZE = '2K';

const TOPICS = [
  {
    key: 'MEME',
    label: 'Small-business meme',
    default_post_type: 'SINGLE_IMAGE',
    visual_mode: 'MEME',
    feed_url: 'https://news.google.com/rss/search?q=small+business+owner+struggles+costs&hl=en-US&gl=US&ceid=US:en',
    brief: 'A painfully relatable moment from running a small business or working solo -- the invoice that never gets paid, the "quick call" that eats an afternoon, wearing six hats before lunch, the subscription you forgot you had. Funny first, true second. The joke must come from one specific operational reality, not a generic "entrepreneur life is hard" gag.'
  },
  {
    key: 'PLAYBOOK',
    label: 'Operating trick',
    default_post_type: 'CAROUSEL',
    visual_mode: 'EDITORIAL',
    feed_url: 'https://news.google.com/rss/search?q=small+business+cash+flow+pricing+late+payment&hl=en-US&gl=US&ceid=US:en',
    brief: 'One concrete tactic that makes a small business run measurably better this week -- pricing, cash flow, late payment, hiring the first employee, cutting admin hours, keeping customers. It must be doable by a one-to-twenty person business with no budget, no consultant and no team behind it.'
  },
  {
    key: 'TOOLSTACK',
    label: 'New or underrated tool',
    default_post_type: 'CAROUSEL',
    visual_mode: 'EDITORIAL',
    feed_url: 'https://news.google.com/rss/search?q=new+software+tool+launch+small+business+solopreneur&hl=en-US&gl=US&ceid=US:en',
    brief: 'A specific, real, currently-available tool that saves a solo operator or small team real hours or real money. Name it. Say what it replaces, roughly what it costs, and who it is WRONG for. No affiliate listicles, no "top 10", nothing that only makes sense above 200 employees.'
  },
  {
    key: 'OPPORTUNITY',
    label: 'Emerging small-business opportunity',
    default_post_type: 'CAROUSEL',
    visual_mode: 'EDITORIAL',
    feed_url: 'https://news.google.com/rss/search?q=new+small+business+opportunity+demand+niche+trend&hl=en-US&gl=US&ceid=US:en',
    brief: 'A genuine, currently-open opening for a new small or solo business -- a demand shift, a rule change, a gap a big incumbent just walked away from, a service local businesses now need and cannot buy well. Concrete enough that a reader could start on it this month, with an honest note on what makes it hard.'
  }
];

// Use a different topic each day so the page never repeats itself, and so both
// post formats stay in use (1 single image + 3 carousels per cycle).
const dayIndex = Math.floor(Date.now() / 86400000);
const topic = TOPICS[dayIndex % TOPICS.length];

const postType = POST_TYPE_MODE === 'AUTO' ? topic.default_post_type : POST_TYPE_MODE;
if (['SINGLE_IMAGE', 'CAROUSEL'].indexOf(postType) === -1) {
  throw new Error('POST_TYPE_MODE must be AUTO, SINGLE_IMAGE or CAROUSEL -- got: ' + POST_TYPE_MODE);
}

return [{
  json: {
    publication_name: PUBLICATION_NAME,
    publication_promise: PUBLICATION_PROMISE,
    author_urn: 'urn:li:organization:' + ORG_ID,
    org_id: ORG_ID,
    linkedin_version: LINKEDIN_VERSION,
    approval_email: APPROVAL_EMAIL,
    post_type: postType,
    post_type_mode: POST_TYPE_MODE,
    min_slides: MIN_SLIDES,
    max_slides: MAX_SLIDES,
    image_aspect: IMAGE_ASPECT,
    image_size: IMAGE_SIZE,
    pillar_key: topic.key,
    pillar_label: topic.label,
    pillar_brief: topic.brief,
    visual_mode: topic.visual_mode,
    feed_url: topic.feed_url,
    run_date: new Date().toISOString().slice(0, 10)
  }
}];

// ===========================================================================
//  Collapse the RSS items into one short block of real, current headlines for the
//  idea agent. Without this the model writes about "new tools" from its training
//  data and quietly presents year-old news as this week's.
//
//  The feed is best-effort: Google News rate-limits and occasionally returns junk.
//  The RSS node is set to continueRegularOutput so a bad fetch degrades to "no
//  headlines" and the run still produces a post, rather than dying at 9am.
// ===========================================================================
const cfg = $('Determine Daily Topic').first().json;
const MAX_HEADLINES = 12;

function formatDate(raw) {
  if (!raw) return '';
  const d = new Date(raw);
  return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
}

const headlines = $input.all()
  .map(function (i) { return i.json || {}; })
  .filter(function (j) { return j.title; })
  .slice(0, MAX_HEADLINES)
  .map(function (j) {
    const when = formatDate(j.isoDate || j.pubDate);
    return '- ' + String(j.title).trim() + (when ? '  (' + when + ')' : '');
  });

return [{
  json: Object.assign({}, cfg, {
    news_context: headlines.length
      ? headlines.join('\n')
      : '(No headlines available this run -- rely on what you know to be true and current, and do not invent recent events.)',
    headline_count: headlines.length
  })
}];

