parameters.jsCode:
// ===========================================================================
//  Normalize the agent output and build the finished image prompts.
//
//  THE BRAND SYSTEM LIVES HERE AND ONLY HERE. The renderer sub-workflow just
//  posts whatever image_prompt this node hands it. Editing style in two places
//  is how a feed drifts out of looking like one publication -- so don't.
// ===========================================================================
const cfg = $('Build News Context Data').first().json;
const o = $input.first().json.output || {};

// -- Brand ------------------------------------------------------------------
const PALETTE = 'Strictly limited palette: warm off-white paper background (#F6F2EA), deep ink navy (#16233A) for all text and linework, warm amber (#E8A33D) and muted teal (#2F7D7B) as the only fills, and at most one brick-orange (#C4552F) accent per image.';

const BRAND = {
  EDITORIAL: 'Flat 2D editorial vector illustration in the style of a modern business publication infographic. ' + PALETTE +
    ' Clean geometric shapes, confident linework, generous negative space, a subtle paper grain. Absolutely no gradients, no drop shadows, no 3D rendering, no photorealism, no stock-photo people, no glossy corporate imagery.',
  MEME: 'Flat 2D comic-style vector illustration, one single punchy scene, deadpan visual humour. ' + PALETTE +
    ' Expressive minimal characters with bold outlines and simple faces. Absolutely no gradients, no 3D rendering, no photorealism, no meme-generator Impact font, no watermarks.'
};

const TYPOGRAPHY = 'Typography: bold condensed geometric sans-serif, tight leading, set in deep ink navy at high contrast against the background.';

// -- Post type: config wins over whatever the model felt like -----------------
const postType = cfg.post_type;

let slides = Array.isArray(o.slides) ? o.slides.slice() : [];
// A slide needs BOTH a headline and a visual subject to render safely --
// missing visual produces a broken "Illustration subject: ." prompt sent
// straight to Gemini, so it's disqualifying just like a missing headline.
slides = slides.filter(function (s) { return s && s.headline && s.visual; });

if (!slides.length) {
  throw new Error('The Post Writer returned no usable slides (missing headline or visual). Raw output: ' + JSON.stringify(o).slice(0, 600));
}

if (postType === 'SINGLE_IMAGE') {
  slides = slides.slice(0, 1);
} else {
  // Enforce the slide count in CODE. The prompt asks for 4 and the parser schema
  // cannot enforce it (numeric JSON-schema constraints in n8n's structured output
  // parser are hard-failing runtime validators, not hints -- they throw instead of
  // degrading). A prompt is not a constraint; this is.
  slides = slides.slice(0, cfg.max_slides);
  if (slides.length < cfg.min_slides) {
    throw new Error('CAROUSEL needs at least ' + cfg.min_slides + ' slides (LinkedIn multiImage rejects fewer) but the writer produced ' +
      slides.length + '. Failing here, before any Gemini call is paid for.');
  }
}

const total = slides.length;

function clean(s, max) {
  return String(s == null ? '' : s).replace(/\*\*/g, '').replace(/\s+/g, ' ').trim().slice(0, max);
}

const planned = slides.map(function (s, i) {
  const headline = clean(s.headline, 38).toUpperCase();
  const sub = clean(s.sub, 70);
  const visual = clean(s.visual, 400);
  // Fallback alt text should never reuse the shouted ALL-CAPS headline --
  // bad for screen readers and not actually descriptive. Fall back to a
  // plain, generic description tied to the pillar instead.
  const alt = clean(s.alt, 100) || ('Illustration for ' + cfg.pillar_label);

  const counter = total > 1
    ? ' Render a small slide counter reading "' + (i + 1) + '/' + total + '" in the bottom-right corner, in navy, no larger than the sub-line.'
    : '';

  const image_prompt = [
    BRAND[cfg.visual_mode] || BRAND.EDITORIAL,
    TYPOGRAPHY,
    'Square 1:1 composition.',
    'Render this headline text EXACTLY, character for character: "' + headline + '".',
    sub ? 'Directly beneath the headline, smaller and lighter, render this text EXACTLY: "' + sub + '".' : '',
    'Spell every character correctly. Do not add, translate, paraphrase, or invent any other text anywhere in the image.',
    'Keep all text inside a safe area at least 8% in from every edge, so nothing is lost when LinkedIn crops the gallery tile.',
    'Illustration subject: ' + visual + '.',
    counter
  ].filter(Boolean).join(' ');

  return {
    slide_index: i,
    headline: headline,
    sub: sub,
    alt_text: alt,
    image_prompt: image_prompt,
    // Passed through to the renderer sub-workflow, which runs on passthrough input.
    author_urn: cfg.author_urn,
    linkedin_version: cfg.linkedin_version,
    image_aspect: cfg.image_aspect,
    image_size: cfg.image_size
  };
});

// -- Commentary --------------------------------------------------------------
// Hashtags go in their own block after a separator rather than jammed into the
// prose, so the post still reads as writing.
const hook = clean(o.hook, 220);
const body = String(o.body == null ? '' : o.body).replace(/\*\*/g, '').trim();
const tags = (Array.isArray(o.hashtags) ? o.hashtags : [])
  .map(function (t) { return String(t).trim().replace(/\s+/g, ''); })
  .filter(function (t) { return t.indexOf('#') === 0 && t.length > 1; });

let commentary = [hook, body].filter(Boolean).join('\n\n');
if (tags.length) commentary += '\n\n' + tags.join(' ');

// LinkedIn hard-limits commentary at 3000 characters and 422s past it.
if (commentary.length > 3000) commentary = commentary.slice(0, 2997).trim() + '...';

return [{
  json: {
    post_type: postType,
    pillar_key: cfg.pillar_key,
    pillar_label: cfg.pillar_label,
    author_urn: cfg.author_urn,
    linkedin_version: cfg.linkedin_version,
    approval_email: cfg.approval_email,
    run_date: cfg.run_date,
    hook: hook,
    commentary: commentary,
    commentary_chars: commentary.length,
    hashtags: tags,
    slide_count: total,
    slides: planned
  }
}];

// The sub-workflow hands back one small object per slide -- never the image
// itself. That is what keeps peak memory bounded at a single image regardless
// of slide count, which is a structural property rather than a smaller number.
const plan = $('Prepare Slide Data').first().json;

const results = $input.all()
  .map(function (i) { return i.json || {}; })
  .filter(function (j) { return j.imageUrn; })
  .sort(function (a, b) { return (a.slideIndex || 0) - (b.slideIndex || 0); });

if (!results.length) {
  throw new Error('No image URNs came back from the renderer. Check the Render LinkedIn Slide (sub) executions -- ' +
    'if they returned {} the sub-workflow read its result off $input instead of by node reference.');
}

if (results.length !== plan.slide_count) {
  throw new Error('Planned ' + plan.slide_count + ' slides but only ' + results.length +
    ' rendered. Publishing a partial carousel would be worse than failing, so stopping here. ' +
    'Note the successful slides are already uploaded to LinkedIn as orphaned image assets.');
}

// SINGLE_IMAGE -> content.media (one image).
// CAROUSEL     -> content.multiImage (LinkedIn requires 2-20 and 422s on one).
let content;
if (plan.post_type === 'CAROUSEL') {
  if (results.length < 2) {
    throw new Error('LinkedIn multiImage needs at least 2 images, got ' + results.length + '.');
  }
  content = {
    multiImage: {
      images: results.map(function (r) {
        return { id: r.imageUrn, altText: r.altText || '' };
      })
    }
  };
} else {
  content = {
    media: { id: results[0].imageUrn, altText: results[0].altText || '' }
  };
}

const previews = results.map(function (r, i) {
  return '  ' + (i + 1) + '. ' + (r.previewUrl || '(preview upload failed -- image still uploaded to LinkedIn OK)');
}).join('\n');

return [{
  json: {
    post_type: plan.post_type,
    pillar_label: plan.pillar_label,
    run_date: plan.run_date,
    author_urn: plan.author_urn,
    linkedin_version: plan.linkedin_version,
    approval_email: plan.approval_email,
    commentary: plan.commentary,
    commentary_chars: plan.commentary_chars,
    slide_count: results.length,
    content: content,
    image_urns: results.map(function (r) { return r.imageUrn; }),
    preview_block: previews
  }
}];

