// LinkedIn returns the new post's URN in the x-restli-id response header rather
// than in the body, so surface it here to make the execution log actually useful.
const r = $input.first().json || {};
const headers = r.headers || {};
const urn = headers['x-restli-id'] || headers['X-RestLi-Id'] || null;

return [{
  json: {
    published: true,
    postUrn: urn,
    postUrl: urn ? 'https://www.linkedin.com/feed/update/' + urn : null,
    statusCode: r.statusCode || null,
    postType: $('Gather Image Data').first().json.post_type,
    slideCount: $('Gather Image Data').first().json.slide_count
  }
}];

// Declined. The slide images were already uploaded to LinkedIn before approval,
// so they now sit as orphaned image assets attached to no post. They are not
// visible anywhere and LinkedIn ages them out on its own, but if you decline
// often it is worth moving image upload to after approval.
return [{
  json: {
    published: false,
    reason: 'Declined in the approval email',
    orphanedImageUrns: $('Gather Image Data').first().json.image_urns,
    postType: $('Gather Image Data').first().json.post_type
  }
}];
